/* ===================== BÀI 3 · Đèn điện tử và các máy tính điện tử sơ khai ===================== */
/* Bài 3 · Đèn điện tử và các máy tính điện tử sơ khai (CM00.03) — sinh bởi tools/author/maytinh/m03.py, không sửa tay.
   Phòng mô phỏng từng bước và bài tập chấm tự động; phần chữ bài học ở lesson.html (nội dung bảo vệ). */
makeMtLab(document.getElementById("lab-l3"),{id:"l3",scenarios:[{"label": "Ví dụ: Đèn ba cực đóng ngắt bằng lưới", "note": "Quan sát electron (chấm xanh) và dòng anốt khi điện áp lưới thay đổi. Hình là mô hình định tính, không theo tỉ lệ.", "steps": [{"t": "Đèn nguội: chưa có electron tự do", "html": "<svg class=\"mt-svg\" viewBox=\"0 0 360 190\" role=\"img\" aria-label=\"Đèn ba cực khi sợi đốt chưa nung\"><rect x=\"110\" y=\"22\" width=\"140\" height=\"160\" rx=\"60\" class=\"soft\" stroke=\"currentColor\" stroke-width=\"1.5\"/><line x1=\"140\" y1=\"50\" x2=\"220\" y2=\"50\" class=\"wire\" stroke-width=\"5\"/><line x1=\"140\" y1=\"100\" x2=\"220\" y2=\"100\" stroke=\"currentColor\" stroke-width=\"2\" stroke-dasharray=\"6 5\"/><line x1=\"140\" y1=\"148\" x2=\"220\" y2=\"148\" class=\"wire\" stroke-width=\"4\"/><path d=\"M145 166 l8 -6 l8 6 l8 -6 l8 6 l8 -6 l8 6 l8 -6 l8 6 l8 -6\" class=\"wire\"/><text x=\"258\" y=\"55\">Anốt (+)<\/text><text x=\"258\" y=\"105\">Lưới —<\/text><text x=\"258\" y=\"153\">Catốt<\/text><text x=\"258\" y=\"172\" class=\"sm\">Sợi đốt<\/text><text x=\"8\" y=\"40\" class=\"sm\">Dòng anốt<\/text><text x=\"8\" y=\"62\" class=\"muted\">≈ 0 (0)<\/text><text x=\"8\" y=\"110\" class=\"sm\">Lưới: —<\/text><\/svg>", "say": "<p>Trong bóng thủy tinh đã hút gần hết không khí. Khi sợi đốt còn nguội, catốt chưa phát electron nên không có dòng điện.<\/p>"}, {"t": "Nung sợi đốt: catốt phát electron", "html": "<svg class=\"mt-svg\" viewBox=\"0 0 360 190\" role=\"img\" aria-label=\"Sợi đốt nóng, catốt phát electron\"><rect x=\"110\" y=\"22\" width=\"140\" height=\"160\" rx=\"60\" class=\"soft\" stroke=\"currentColor\" stroke-width=\"1.5\"/><line x1=\"140\" y1=\"50\" x2=\"220\" y2=\"50\" class=\"wire\" stroke-width=\"5\"/><line x1=\"140\" y1=\"100\" x2=\"220\" y2=\"100\" stroke=\"currentColor\" stroke-width=\"2\" stroke-dasharray=\"6 5\"/><line x1=\"140\" y1=\"148\" x2=\"220\" y2=\"148\" class=\"wire\" stroke-width=\"4\"/><path d=\"M145 166 l8 -6 l8 6 l8 -6 l8 6 l8 -6 l8 6 l8 -6 l8 6 l8 -6\" class=\"wire on\"/><circle cx=\"140\" cy=\"138\" r=\"4\" class=\"acc\"/><circle cx=\"165\" cy=\"138\" r=\"4\" class=\"acc\"/><circle cx=\"190\" cy=\"138\" r=\"4\" class=\"acc\"/><circle cx=\"215\" cy=\"138\" r=\"4\" class=\"acc\"/><text x=\"258\" y=\"55\">Anốt (+)<\/text><text x=\"258\" y=\"105\">Lưới —<\/text><text x=\"258\" y=\"153\">Catốt<\/text><text x=\"258\" y=\"172\" class=\"sm\">Sợi đốt (nóng)<\/text><text x=\"8\" y=\"40\" class=\"sm\">Dòng anốt<\/text><text x=\"8\" y=\"62\" class=\"muted\">≈ 0 (0)<\/text><text x=\"8\" y=\"110\" class=\"sm\">Lưới: —<\/text><\/svg>", "say": "<p>Catốt nóng làm electron thoát ra (phát xạ nhiệt điện tử). Anốt nối cực dương nên hút electron về phía nó.<\/p>"}, {"t": "Lưới âm mạnh: electron bị đẩy lại, dòng ≈ 0", "html": "<svg class=\"mt-svg\" viewBox=\"0 0 360 190\" role=\"img\" aria-label=\"Lưới âm mạnh chặn electron\"><rect x=\"110\" y=\"22\" width=\"140\" height=\"160\" rx=\"60\" class=\"soft\" stroke=\"currentColor\" stroke-width=\"1.5\"/><line x1=\"140\" y1=\"50\" x2=\"220\" y2=\"50\" class=\"wire\" stroke-width=\"5\"/><line x1=\"140\" y1=\"100\" x2=\"220\" y2=\"100\" stroke=\"currentColor\" stroke-width=\"2\" stroke-dasharray=\"6 5\"/><line x1=\"140\" y1=\"148\" x2=\"220\" y2=\"148\" class=\"wire\" stroke-width=\"4\"/><path d=\"M145 166 l8 -6 l8 6 l8 -6 l8 6 l8 -6 l8 6 l8 -6 l8 6 l8 -6\" class=\"wire on\"/><circle cx=\"140\" cy=\"138\" r=\"4\" class=\"acc\"/><circle cx=\"165\" cy=\"138\" r=\"4\" class=\"acc\"/><circle cx=\"190\" cy=\"138\" r=\"4\" class=\"acc\"/><circle cx=\"215\" cy=\"138\" r=\"4\" class=\"acc\"/><circle cx=\"150\" cy=\"118\" r=\"4\" class=\"acc\"/><circle cx=\"180\" cy=\"118\" r=\"4\" class=\"acc\"/><circle cx=\"205\" cy=\"118\" r=\"4\" class=\"acc\"/><text x=\"258\" y=\"55\">Anốt (+)<\/text><text x=\"258\" y=\"105\">Lưới âm mạnh<\/text><text x=\"258\" y=\"153\">Catốt<\/text><text x=\"258\" y=\"172\" class=\"sm\">Sợi đốt (nóng)<\/text><text x=\"8\" y=\"40\" class=\"sm\">Dòng anốt<\/text><text x=\"8\" y=\"62\" class=\"muted\">≈ 0 (0)<\/text><text x=\"8\" y=\"110\" class=\"sm\">Lưới: âm mạnh<\/text><\/svg>", "ask": {"q": "Đặt lưới ở điện áp âm mạnh so với catốt. Dòng tới anốt thế nào?", "o": ["Tăng mạnh", "Gần như bằng 0", "Không đổi"], "a": 1}, "say": "<p>Electron mang điện âm bị lưới âm đẩy ngược lại, gần như không tới được anốt. Trạng thái này dùng như <b>công tắc mở<\/b>, ứng với 0.<\/p>"}, {"t": "Lưới bớt âm: electron đi qua, có dòng", "html": "<svg class=\"mt-svg\" viewBox=\"0 0 360 190\" role=\"img\" aria-label=\"Lưới bớt âm, electron tới anốt\"><rect x=\"110\" y=\"22\" width=\"140\" height=\"160\" rx=\"60\" class=\"soft\" stroke=\"currentColor\" stroke-width=\"1.5\"/><line x1=\"140\" y1=\"50\" x2=\"220\" y2=\"50\" class=\"wire on\" stroke-width=\"5\"/><line x1=\"140\" y1=\"100\" x2=\"220\" y2=\"100\" stroke=\"currentColor\" stroke-width=\"2\" stroke-dasharray=\"6 5\"/><line x1=\"140\" y1=\"148\" x2=\"220\" y2=\"148\" class=\"wire\" stroke-width=\"4\"/><path d=\"M145 166 l8 -6 l8 6 l8 -6 l8 6 l8 -6 l8 6 l8 -6 l8 6 l8 -6\" class=\"wire on\"/><circle cx=\"140\" cy=\"138\" r=\"4\" class=\"acc\"/><circle cx=\"165\" cy=\"138\" r=\"4\" class=\"acc\"/><circle cx=\"190\" cy=\"138\" r=\"4\" class=\"acc\"/><circle cx=\"215\" cy=\"138\" r=\"4\" class=\"acc\"/><circle cx=\"150\" cy=\"112\" r=\"4\" class=\"acc\"/><circle cx=\"180\" cy=\"88\" r=\"4\" class=\"acc\"/><circle cx=\"205\" cy=\"66\" r=\"4\" class=\"acc\"/><circle cx=\"165\" cy=\"76\" r=\"4\" class=\"acc\"/><circle cx=\"195\" cy=\"104\" r=\"4\" class=\"acc\"/><text x=\"258\" y=\"55\">Anốt (+)<\/text><text x=\"258\" y=\"105\">Lưới bớt âm<\/text><text x=\"258\" y=\"153\">Catốt<\/text><text x=\"258\" y=\"172\" class=\"sm\">Sợi đốt (nóng)<\/text><text x=\"8\" y=\"40\" class=\"sm\">Dòng anốt<\/text><text x=\"8\" y=\"62\" class=\"warm\">CÓ dòng (1)<\/text><text x=\"8\" y=\"110\" class=\"sm\">Lưới: bớt âm<\/text><\/svg>", "say": "<p>Chỉ cần đổi điện áp nhỏ ở lưới là điều khiển được dòng lớn ở anốt: đèn vừa <b>khuếch đại<\/b> vừa làm <b>công tắc<\/b>, mà không có bộ phận nào chuyển động.<\/p>"}]}, {"label": "Ví dụ: Rơ-le và đèn: số lần đóng ngắt", "note": "Thời gian đóng ngắt là số giả định để so sánh cỡ độ lớn (1 ms và 1 µs).", "steps": [{"t": "Giả định thời gian một lần đóng ngắt", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Linh kiện<\/th><th scope=\"col\">Thời gian một lần đóng ngắt (giả định)<\/th><\/tr><\/thead><tbody><tr><td>Rơ-le<\/td><td>1 ms = 0,001 s<\/td><\/tr><tr><td>Đèn điện tử<\/td><td>1 µs = 0,000 001 s<\/td><\/tr><\/tbody><\/table><p class=\"mt-calc\">Hai con số chỉ để so sánh cỡ độ lớn: rơ-le cỡ mili giây, đèn cỡ micro giây.<\/p>", "say": "<p>Rơ-le có tiếp điểm kim loại phải di chuyển; đèn chỉ cần đổi điện áp lưới.<\/p>"}, {"t": "Rơ-le: tối đa 1 000 lần mỗi giây", "html": "<p class=\"mt-calc\">1 s ÷ 0,001 s = <b>1 000<\/b> lần<\/p><div class=\"mt-bars\"><div><span>Rơ-le<\/span><span><i class=\"w\" style=\"width:100.0%\"><\/i><em>1 000 lần/s<\/em><\/span><\/div><\/div><p class=\"mt-cap\">Chỉ tính thời gian chuyển trạng thái, bỏ qua mọi chậm trễ khác.<\/p>", "ask": {"q": "Với 1 ms mỗi lần, rơ-le đóng ngắt được tối đa bao nhiêu lần mỗi giây?", "o": ["100", "1 000", "1 000 000"], "a": 1}}, {"t": "Đèn: tối đa 1 000 000 lần mỗi giây", "html": "<p class=\"mt-calc\">1 s ÷ 0,000 001 s = <b>1 000 000<\/b> lần<\/p><div class=\"mt-bars\"><div><span>Rơ-le<\/span><span><i class=\"w\" style=\"width:0.5%\"><\/i><em>1 000 lần/s<\/em><\/span><\/div><div><span>Đèn điện tử<\/span><span><i class=\"\" style=\"width:100.0%\"><\/i><em>1 000 000 lần/s<\/em><\/span><\/div><\/div>", "say": "<p>Gấp 1 000 lần. Thanh của rơ-le gần như biến mất khi vẽ cùng tỉ lệ. Cái giá phải trả: mỗi đèn cần điện nung sợi đốt, tỏa nhiệt và sợi đốt có thể đứt.<\/p>"}]}, {"label": "Ví dụ: ENIAC lập trình bằng dây cắm", "note": "Chương trình là cách nối dây giữa các khối. Đổi bài toán là nối lại dây.", "steps": [{"t": "Bài toán: tính (5 + 7) × 2", "html": "<div class=\"mt-flow\"><div class=\"mt-box\"><b>Bộ tích lũy A1<\/b><small>giữ 5<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>Bộ tích lũy A2<\/b><small>giữ 7<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>Bộ nhân<\/b><small>chờ<\/small><\/div><\/div>", "say": "<p>ENIAC gồm nhiều khối (bộ tích lũy, bộ nhân, bảng hàm…). Chương trình là cách <b>nối dây<\/b> giữa các khối và cách đặt công tắc trên từng khối.<\/p>"}, {"t": "Cắm dây: A2 cộng vào A1", "html": "<div class=\"mt-flow\"><div class=\"mt-box on\"><b>Bộ tích lũy A1<\/b><small>5 + 7 = 12<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box warn\"><b>dây cắm<\/b><small>A2 → A1<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>Bộ tích lũy A2<\/b><small>7<\/small><\/div><\/div>", "say": "<p>Một dây chở số, một dây chở xung “bắt đầu” sang khối kế tiếp.<\/p>"}, {"t": "Cắm dây: A1 sang bộ nhân", "html": "<div class=\"mt-flow\"><div class=\"mt-box\"><b>Bộ tích lũy A1<\/b><small>12<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box warn\"><b>dây cắm<\/b><small>A1 → bộ nhân<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box on\"><b>Bộ nhân<\/b><small>12 × 2 = 24<\/small><\/div><\/div>", "ask": {"q": "Muốn đổi sang tính (5 − 7) × 2 trên ENIAC lúc đầu, phải làm gì?", "o": ["Gõ chương trình mới vào bộ nhớ", "Rút cắm lại dây và đặt lại công tắc", "Thay toàn bộ đèn điện tử"], "a": 1}}, {"t": "Đổi bài toán = nối lại dây", "html": "<div class=\"mt-flow\"><div class=\"mt-box dim\"><b>Bộ tích lũy A1<\/b><small>?<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box warn\"><b>dây cắm<\/b><small>tháo ra, cắm lại<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box dim\"><b>Bộ nhân<\/b><small>?<\/small><\/div><\/div>", "say": "<p>ENIAC tính rất nhanh so với thời đó, nhưng chuẩn bị một chương trình mới có thể mất nhiều ngày. Đây chính là vấn đề mà ý tưởng lưu chương trình trong bộ nhớ giải quyết.<\/p>"}]}, {"label": "Ví dụ: Máy lưu chương trình chạy 4 lệnh", "note": "PC chỉ ô nào thì ô đó được đọc như lệnh. Nhìn ACC thay đổi sau từng lệnh.", "steps": [{"t": "Chương trình và dữ liệu cùng nằm trong bộ nhớ", "html": "<div class=\"mt-flow\"><div class=\"mt-box\"><table class=\"mt-tab\"><thead><tr><th scope=\"col\">Địa chỉ<\/th><th scope=\"col\">Nội dung ô nhớ<\/th><\/tr><\/thead><tbody><tr><td>0<\/td><td>LOAD [5]<\/td><\/tr><tr><td>1<\/td><td>ADD [6]<\/td><\/tr><tr><td>2<\/td><td>STORE [7]<\/td><\/tr><tr><td>3<\/td><td>HALT<\/td><\/tr><tr><td>5<\/td><td>5<\/td><\/tr><tr><td>6<\/td><td>7<\/td><\/tr><tr><td>7<\/td><td>0<\/td><\/tr><\/tbody><\/table><\/div><div class=\"mt-box\"><b>CPU<\/b><table class=\"mt-tab\"><thead><tr><th scope=\"col\">PC (ô lệnh)<\/th><th scope=\"col\">ACC<\/th><\/tr><\/thead><tbody><tr><td>—<\/td><td>—<\/td><\/tr><\/tbody><\/table><\/div><\/div>", "say": "<p>Ô 0–3 chứa lệnh, ô 5–7 chứa số. Bộ nhớ không phân biệt hai loại; chỉ có <b>PC<\/b> (bộ đếm chương trình) cho biết ô nào được đọc như lệnh; <b>ACC<\/b> (thanh ghi tích lũy) giữ kết quả tạm.<\/p>"}, {"t": "Ô 0: LOAD [5] → ACC = 5", "html": "<div class=\"mt-flow\"><div class=\"mt-box\"><table class=\"mt-tab\"><thead><tr><th scope=\"col\">Địa chỉ<\/th><th scope=\"col\">Nội dung ô nhớ<\/th><\/tr><\/thead><tbody><tr><td>0<\/td><td class=\"hi\">LOAD [5]<\/td><\/tr><tr><td>1<\/td><td>ADD [6]<\/td><\/tr><tr><td>2<\/td><td>STORE [7]<\/td><\/tr><tr><td>3<\/td><td>HALT<\/td><\/tr><tr><td>5<\/td><td>5<\/td><\/tr><tr><td>6<\/td><td>7<\/td><\/tr><tr><td>7<\/td><td>0<\/td><\/tr><\/tbody><\/table><\/div><div class=\"mt-box\"><b>CPU<\/b><table class=\"mt-tab\"><thead><tr><th scope=\"col\">PC (ô lệnh)<\/th><th scope=\"col\">ACC<\/th><\/tr><\/thead><tbody><tr><td>0<\/td><td>5<\/td><\/tr><\/tbody><\/table><small>Đọc lệnh ở ô 0, nạp số trong ô 5 vào ACC<\/small><\/div><\/div>"}, {"t": "Ô 1: ADD [6] → ACC = 12", "html": "<div class=\"mt-flow\"><div class=\"mt-box\"><table class=\"mt-tab\"><thead><tr><th scope=\"col\">Địa chỉ<\/th><th scope=\"col\">Nội dung ô nhớ<\/th><\/tr><\/thead><tbody><tr><td>0<\/td><td>LOAD [5]<\/td><\/tr><tr><td>1<\/td><td class=\"hi\">ADD [6]<\/td><\/tr><tr><td>2<\/td><td>STORE [7]<\/td><\/tr><tr><td>3<\/td><td>HALT<\/td><\/tr><tr><td>5<\/td><td>5<\/td><\/tr><tr><td>6<\/td><td>7<\/td><\/tr><tr><td>7<\/td><td>0<\/td><\/tr><\/tbody><\/table><\/div><div class=\"mt-box\"><b>CPU<\/b><table class=\"mt-tab\"><thead><tr><th scope=\"col\">PC (ô lệnh)<\/th><th scope=\"col\">ACC<\/th><\/tr><\/thead><tbody><tr><td>1<\/td><td>12<\/td><\/tr><\/tbody><\/table><small>Cộng số trong ô 6 vào ACC<\/small><\/div><\/div>", "ask": {"q": "ACC đang là 5, ô 6 chứa 7. Sau lệnh ADD [6], ACC bằng bao nhiêu?", "o": ["7", "12", "57"], "a": 1}}, {"t": "Ô 2: STORE [7] → ô 7 = 12", "html": "<div class=\"mt-flow\"><div class=\"mt-box\"><table class=\"mt-tab\"><thead><tr><th scope=\"col\">Địa chỉ<\/th><th scope=\"col\">Nội dung ô nhớ<\/th><\/tr><\/thead><tbody><tr><td>0<\/td><td>LOAD [5]<\/td><\/tr><tr><td>1<\/td><td>ADD [6]<\/td><\/tr><tr><td>2<\/td><td class=\"hi\">STORE [7]<\/td><\/tr><tr><td>3<\/td><td>HALT<\/td><\/tr><tr><td>5<\/td><td>5<\/td><\/tr><tr><td>6<\/td><td>7<\/td><\/tr><tr><td>7<\/td><td class=\"new\">12<\/td><\/tr><\/tbody><\/table><\/div><div class=\"mt-box\"><b>CPU<\/b><table class=\"mt-tab\"><thead><tr><th scope=\"col\">PC (ô lệnh)<\/th><th scope=\"col\">ACC<\/th><\/tr><\/thead><tbody><tr><td>2<\/td><td>12<\/td><\/tr><\/tbody><\/table><small>Ghi ACC vào ô 7<\/small><\/div><\/div>"}, {"t": "Ô 3: HALT → dừng", "html": "<div class=\"mt-flow\"><div class=\"mt-box\"><table class=\"mt-tab\"><thead><tr><th scope=\"col\">Địa chỉ<\/th><th scope=\"col\">Nội dung ô nhớ<\/th><\/tr><\/thead><tbody><tr><td>0<\/td><td>LOAD [5]<\/td><\/tr><tr><td>1<\/td><td>ADD [6]<\/td><\/tr><tr><td>2<\/td><td>STORE [7]<\/td><\/tr><tr><td>3<\/td><td class=\"hi\">HALT<\/td><\/tr><tr><td>5<\/td><td>5<\/td><\/tr><tr><td>6<\/td><td>7<\/td><\/tr><tr><td>7<\/td><td>12<\/td><\/tr><\/tbody><\/table><\/div><div class=\"mt-box\"><b>CPU<\/b><table class=\"mt-tab\"><thead><tr><th scope=\"col\">PC (ô lệnh)<\/th><th scope=\"col\">ACC<\/th><\/tr><\/thead><tbody><tr><td>3<\/td><td>12<\/td><\/tr><\/tbody><\/table><small>Máy dừng; kết quả 12 nằm ở ô 7<\/small><\/div><\/div>", "say": "<p>Mỗi lệnh đi qua cùng một vòng: <b>đọc lệnh<\/b> ở ô PC chỉ tới, <b>thực hiện<\/b>, rồi PC sang ô kế tiếp. Chương 5 sẽ học kỹ vòng này.<\/p>"}]}, {"label": "Ví dụ: Đổi chương trình bằng cách sửa ô nhớ", "note": "Chỉ sửa một ô (ADD thành SUB), không cần nối lại dây.", "steps": [{"t": "Chương trình cũ: 5 + 7", "html": "<div class=\"mt-flow\"><div class=\"mt-box\"><table class=\"mt-tab\"><thead><tr><th scope=\"col\">Địa chỉ<\/th><th scope=\"col\">Nội dung ô nhớ<\/th><\/tr><\/thead><tbody><tr><td>0<\/td><td>LOAD [5]<\/td><\/tr><tr><td>1<\/td><td>ADD [6]<\/td><\/tr><tr><td>2<\/td><td>STORE [7]<\/td><\/tr><tr><td>3<\/td><td>HALT<\/td><\/tr><tr><td>5<\/td><td>5<\/td><\/tr><tr><td>6<\/td><td>7<\/td><\/tr><tr><td>7<\/td><td>0<\/td><\/tr><\/tbody><\/table><\/div><div class=\"mt-box\"><b>CPU<\/b><table class=\"mt-tab\"><thead><tr><th scope=\"col\">PC (ô lệnh)<\/th><th scope=\"col\">ACC<\/th><\/tr><\/thead><tbody><tr><td>—<\/td><td>—<\/td><\/tr><\/tbody><\/table><\/div><\/div>", "say": "<p>Muốn tính 5 − 7 thay vì 5 + 7.<\/p>"}, {"t": "Sửa đúng một ô nhớ: ô 1 thành SUB [6]", "html": "<div class=\"mt-flow\"><div class=\"mt-box\"><table class=\"mt-tab\"><thead><tr><th scope=\"col\">Địa chỉ<\/th><th scope=\"col\">Nội dung ô nhớ<\/th><\/tr><\/thead><tbody><tr><td>0<\/td><td>LOAD [5]<\/td><\/tr><tr><td>1<\/td><td class=\"new\">SUB [6]<\/td><\/tr><tr><td>2<\/td><td>STORE [7]<\/td><\/tr><tr><td>3<\/td><td>HALT<\/td><\/tr><tr><td>5<\/td><td>5<\/td><\/tr><tr><td>6<\/td><td>7<\/td><\/tr><tr><td>7<\/td><td>0<\/td><\/tr><\/tbody><\/table><\/div><div class=\"mt-box\"><b>CPU<\/b><table class=\"mt-tab\"><thead><tr><th scope=\"col\">PC (ô lệnh)<\/th><th scope=\"col\">ACC<\/th><\/tr><\/thead><tbody><tr><td>—<\/td><td>—<\/td><\/tr><\/tbody><\/table><\/div><\/div>", "say": "<p>Với máy lưu chương trình, đổi chương trình chỉ là <b>ghi lại ô nhớ<\/b>, nhanh như ghi dữ liệu. Với ENIAC lúc đầu, việc tương tự là rút cắm lại dây, có khi mất nhiều ngày.<\/p>"}, {"t": "Chạy lại: ACC = 5 − 7 = −2", "html": "<div class=\"mt-flow\"><div class=\"mt-box\"><table class=\"mt-tab\"><thead><tr><th scope=\"col\">Địa chỉ<\/th><th scope=\"col\">Nội dung ô nhớ<\/th><\/tr><\/thead><tbody><tr><td>0<\/td><td>LOAD [5]<\/td><\/tr><tr><td>1<\/td><td>SUB [6]<\/td><\/tr><tr><td>2<\/td><td>STORE [7]<\/td><\/tr><tr><td>3<\/td><td class=\"hi\">HALT<\/td><\/tr><tr><td>5<\/td><td>5<\/td><\/tr><tr><td>6<\/td><td>7<\/td><\/tr><tr><td>7<\/td><td class=\"new\">−2<\/td><\/tr><\/tbody><\/table><\/div><div class=\"mt-box\"><b>CPU<\/b><table class=\"mt-tab\"><thead><tr><th scope=\"col\">PC (ô lệnh)<\/th><th scope=\"col\">ACC<\/th><\/tr><\/thead><tbody><tr><td>3<\/td><td>-2<\/td><\/tr><\/tbody><\/table><\/div><\/div>", "ask": {"q": "Sau khi đổi ô 1 thành SUB [6] và chạy lại, ô 7 chứa số nào?", "o": ["12", "−2", "2"], "a": 1}}]}, {"label": "Bẫy: Thêm linh kiện, máy hỏng thường xuyên hơn", "note": "Số liệu giả định 100 000 giờ cho một đèn. Quan sát thời gian trung bình giữa hai lần hỏng giảm khi số đèn tăng.", "steps": [{"t": "Giả định: mỗi đèn trung bình 100 000 giờ hỏng một lần", "html": "<p class=\"mt-calc\">Giả định minh họa, không phải số liệu đo của ENIAC. Các đèn hỏng độc lập; một đèn hỏng là cả máy dừng.<\/p>", "say": "<p>100 000 giờ là hơn 11 năm. Một đèn đơn lẻ có vẻ rất bền.<\/p>"}, {"t": "1 đèn → trung bình 100 000 giờ có một đèn hỏng", "html": "<p class=\"mt-calc\">MTBF hệ thống ≈ 100 000 ÷ 1 = <b>100 000 giờ<\/b><\/p><div class=\"mt-bars\"><div><span>1 đèn<\/span><span><i class=\"\" style=\"width:100.0%\"><\/i><em>100 000 giờ<\/em><\/span><\/div><\/div>"}, {"t": "100 đèn → trung bình 1 000 giờ có một đèn hỏng", "html": "<p class=\"mt-calc\">MTBF hệ thống ≈ 100 000 ÷ 100 = <b>1 000 giờ<\/b><\/p><div class=\"mt-bars\"><div><span>1 đèn<\/span><span><i class=\"\" style=\"width:100.0%\"><\/i><em>100 000 giờ<\/em><\/span><\/div><div><span>100 đèn<\/span><span><i class=\"\" style=\"width:1.0%\"><\/i><em>1 000 giờ<\/em><\/span><\/div><\/div>"}, {"t": "1 000 đèn → trung bình 100 giờ có một đèn hỏng", "html": "<p class=\"mt-calc\">MTBF hệ thống ≈ 100 000 ÷ 1 000 = <b>100 giờ<\/b><\/p><div class=\"mt-bars\"><div><span>1 đèn<\/span><span><i class=\"\" style=\"width:100.0%\"><\/i><em>100 000 giờ<\/em><\/span><\/div><div><span>100 đèn<\/span><span><i class=\"\" style=\"width:1.0%\"><\/i><em>1 000 giờ<\/em><\/span><\/div><div><span>1 000 đèn<\/span><span><i class=\"\" style=\"width:0.5%\"><\/i><em>100 giờ<\/em><\/span><\/div><\/div>"}, {"t": "18 000 đèn → trung bình 5,6 giờ có một đèn hỏng", "html": "<p class=\"mt-calc\">MTBF hệ thống ≈ 100 000 ÷ 18 000 = <b>5,6 giờ<\/b><\/p><div class=\"mt-bars\"><div><span>1 đèn<\/span><span><i class=\"\" style=\"width:100.0%\"><\/i><em>100 000 giờ<\/em><\/span><\/div><div><span>100 đèn<\/span><span><i class=\"\" style=\"width:1.0%\"><\/i><em>1 000 giờ<\/em><\/span><\/div><div><span>1 000 đèn<\/span><span><i class=\"\" style=\"width:0.5%\"><\/i><em>100 giờ<\/em><\/span><\/div><div><span>18 000 đèn<\/span><span><i class=\"e\" style=\"width:0.5%\"><\/i><em>5,6 giờ<\/em><\/span><\/div><\/div>", "ask": {"q": "Với 18 000 đèn như vậy, trung bình bao lâu có một đèn hỏng?", "o": ["Khoảng 11 năm", "Khoảng 5,6 giờ", "Khoảng 18 000 giờ"], "a": 1}, "say": "<p>Thêm linh kiện thì máy hỏng thường xuyên hơn: tuổi thọ trung bình của cả hệ <b>chia<\/b> cho số linh kiện. Người vận hành máy đèn điện tử phải tìm và thay đèn hỏng thường xuyên; tuổi thọ đèn là một giới hạn lớn trước khi có transistor (Bài 4).<\/p>"}]}, {"label": "Lỗi: Ghi nhầm địa chỉ, đè lên chương trình", "note": "Chương trình và dữ liệu chung bộ nhớ, nên STORE sai địa chỉ có thể làm hỏng chính chương trình.", "steps": [{"t": "Lỗi gõ: ô 2 là STORE [1] thay vì STORE [7]", "html": "<div class=\"mt-flow\"><div class=\"mt-box\"><table class=\"mt-tab\"><thead><tr><th scope=\"col\">Địa chỉ<\/th><th scope=\"col\">Nội dung ô nhớ<\/th><\/tr><\/thead><tbody><tr><td>0<\/td><td>LOAD [5]<\/td><\/tr><tr><td>1<\/td><td>ADD [6]<\/td><\/tr><tr><td>2<\/td><td class=\"new\">STORE [1]<\/td><\/tr><tr><td>3<\/td><td>HALT<\/td><\/tr><tr><td>5<\/td><td>5<\/td><\/tr><tr><td>6<\/td><td>7<\/td><\/tr><tr><td>7<\/td><td>0<\/td><\/tr><\/tbody><\/table><\/div><div class=\"mt-box\"><b>CPU<\/b><table class=\"mt-tab\"><thead><tr><th scope=\"col\">PC (ô lệnh)<\/th><th scope=\"col\">ACC<\/th><\/tr><\/thead><tbody><tr><td>—<\/td><td>—<\/td><\/tr><\/tbody><\/table><\/div><\/div>", "say": "<p>Chương trình và dữ liệu dùng chung bộ nhớ, nên một lệnh ghi sai địa chỉ có thể ghi đè lên chính chương trình.<\/p>"}, {"t": "Chạy: LOAD, ADD → ACC = 12", "html": "<div class=\"mt-flow\"><div class=\"mt-box\"><table class=\"mt-tab\"><thead><tr><th scope=\"col\">Địa chỉ<\/th><th scope=\"col\">Nội dung ô nhớ<\/th><\/tr><\/thead><tbody><tr><td>0<\/td><td>LOAD [5]<\/td><\/tr><tr><td>1<\/td><td class=\"hi\">ADD [6]<\/td><\/tr><tr><td>2<\/td><td>STORE [1]<\/td><\/tr><tr><td>3<\/td><td>HALT<\/td><\/tr><tr><td>5<\/td><td>5<\/td><\/tr><tr><td>6<\/td><td>7<\/td><\/tr><tr><td>7<\/td><td>0<\/td><\/tr><\/tbody><\/table><\/div><div class=\"mt-box\"><b>CPU<\/b><table class=\"mt-tab\"><thead><tr><th scope=\"col\">PC (ô lệnh)<\/th><th scope=\"col\">ACC<\/th><\/tr><\/thead><tbody><tr><td>1<\/td><td>12<\/td><\/tr><\/tbody><\/table><\/div><\/div>"}, {"t": "STORE [1]: ghi 12 đè lên lệnh ADD", "html": "<div class=\"mt-flow\"><div class=\"mt-box\"><table class=\"mt-tab\"><thead><tr><th scope=\"col\">Địa chỉ<\/th><th scope=\"col\">Nội dung ô nhớ<\/th><\/tr><\/thead><tbody><tr><td>0<\/td><td>LOAD [5]<\/td><\/tr><tr><td>1<\/td><td class=\"new\">12<\/td><\/tr><tr><td>2<\/td><td class=\"hi\">STORE [1]<\/td><\/tr><tr><td>3<\/td><td>HALT<\/td><\/tr><tr><td>5<\/td><td>5<\/td><\/tr><tr><td>6<\/td><td>7<\/td><\/tr><tr><td>7<\/td><td>0<\/td><\/tr><\/tbody><\/table><\/div><div class=\"mt-box\"><b>CPU<\/b><table class=\"mt-tab\"><thead><tr><th scope=\"col\">PC (ô lệnh)<\/th><th scope=\"col\">ACC<\/th><\/tr><\/thead><tbody><tr><td>2<\/td><td>12<\/td><\/tr><\/tbody><\/table><\/div><\/div>", "ask": {"q": "Lệnh STORE [1] ghi 12 vào ô 1. Ô 1 lúc này chứa gì?", "o": ["Vẫn là ADD [6]", "Số 12", "Ô trống"], "a": 1}}, {"t": "Chạy lại lần 2: ô 1 không còn là lệnh", "html": "<div class=\"mt-flow\"><div class=\"mt-box\"><table class=\"mt-tab\"><thead><tr><th scope=\"col\">Địa chỉ<\/th><th scope=\"col\">Nội dung ô nhớ<\/th><\/tr><\/thead><tbody><tr><td>0<\/td><td>LOAD [5]<\/td><\/tr><tr><td>1<\/td><td class=\"hi\">12<\/td><\/tr><tr><td>2<\/td><td>STORE [1]<\/td><\/tr><tr><td>3<\/td><td>HALT<\/td><\/tr><tr><td>5<\/td><td>5<\/td><\/tr><tr><td>6<\/td><td>7<\/td><\/tr><tr><td>7<\/td><td>0<\/td><\/tr><\/tbody><\/table><\/div><div class=\"mt-box\"><b>CPU<\/b><table class=\"mt-tab\"><thead><tr><th scope=\"col\">PC (ô lệnh)<\/th><th scope=\"col\">ACC<\/th><\/tr><\/thead><tbody><tr><td>1<\/td><td>5<\/td><\/tr><\/tbody><\/table><small>Trong máy mô hình này, số 12 không phải mã lệnh hợp lệ → máy dừng báo lỗi<\/small><\/div><\/div>", "say": "<p>Kết quả lần 1 không nằm ở ô 7, và lần chạy sau hỏng vì chương trình đã bị sửa. Máy tính ngày nay đánh dấu vùng nhớ chứa mã là “chỉ đọc” để chặn kiểu lỗi này (Chương 8).<\/p>"}]}]});
makeMtEx(document.getElementById("ex-l3"),"l3",[{"kind": "pick", "t": "Máy nào, công nghệ nào?", "d": "<p>Chọn nhóm đúng cho từng máy.<\/p>", "cats": ["Điện cơ (rơ-le, bộ phận cơ khí)", "Điện tử, không lập trình được", "Điện tử, đổi chương trình bằng dây cắm và công tắc", "Điện tử, lưu chương trình trong bộ nhớ"], "items": [{"q": "Z3 (1941)", "a": 0}, {"q": "Harvard Mark I (1944)", "a": 0}, {"q": "ABC (1937–1942)", "a": 1}, {"q": "Colossus (1943–1944)", "a": 2}, {"q": "ENIAC khi hoàn thành (1945)", "a": 2}, {"q": "Manchester Baby (1948)", "a": 3}, {"q": "EDSAC (1949)", "a": 3}], "hints": ["Z3 và Harvard Mark I dùng linh kiện có bộ phận chuyển động.", "ABC tính bằng điện tử nhưng chỉ làm một loại bài toán.", "Chỉ các máy từ năm 1948 trong danh sách mới lưu chương trình trong bộ nhớ."], "why": "Z3 và Mark I là điện cơ; ABC điện tử nhưng không lập trình được; Colossus và ENIAC lúc đầu đặt chương trình bằng dây cắm, công tắc; Manchester Baby và EDSAC lưu chương trình trong bộ nhớ."}, {"kind": "num", "t": "Tốc độ và độ tin cậy", "d": "<p>Dùng các giả định trong bài: một linh kiện hỏng là cả máy dừng, các linh kiện hỏng độc lập. Làm tròn tới 2 chữ số thập phân.<\/p>", "items": [{"q": "Rơ-le mất 1 ms mỗi lần đóng ngắt. Tối đa bao nhiêu lần mỗi giây?", "a": 1000, "unit": "lần"}, {"q": "1 000 linh kiện, mỗi cái MTBF 50 000 giờ. MTBF của máy?", "a": 50, "tol": 0.01, "unit": "giờ"}, {"q": "18 000 đèn, mỗi đèn MTBF 100 000 giờ. MTBF của máy?", "a": 5.555555555555555, "tol": 0.01, "unit": "giờ"}, {"q": "Thay bằng đèn tốt gấp đôi (200 000 giờ), vẫn 18 000 đèn. MTBF của máy?", "a": 11.11111111111111, "tol": 0.01, "unit": "giờ"}], "hints": ["Số lần mỗi giây = 1 giây chia cho thời gian một lần (đổi 1 ms = 0,001 s).", "MTBF máy ≈ MTBF linh kiện ÷ số linh kiện.", "100 000 ÷ 18 000 ≈ 5,56; đèn tốt gấp đôi thì MTBF máy cũng gấp đôi."], "why": "1 ÷ 0,001 = 1 000 lần/s; 50 000 ÷ 1 000 = 50 giờ; 100 000 ÷ 18 000 ≈ 5,56 giờ; 200 000 ÷ 18 000 ≈ 11,11 giờ. Muốn máy bền hơn thì phải giảm số linh kiện hoặc dùng linh kiện bền hơn, đó là điều transistor mang lại."}, {"kind": "order", "t": "Xếp các mốc theo thời gian", "d": "<p>Xếp từ sớm nhất (trên cùng) tới muộn nhất.<\/p>", "items": ["Fleming chế tạo đèn hai cực", "De Forest tạo ra đèn ba cực", "Z3 của Zuse hoạt động", "ENIAC được công bố", "Manchester Baby chạy chương trình lưu trong bộ nhớ", "EDSAC bắt đầu phục vụ tính toán thường xuyên", "UNIVAC I được giao cho Cục Điều tra dân số Hoa Kỳ"], "hints": ["Hai loại đèn ra đời đầu thế kỷ 20, cách nhau 2 năm.", "Z3 hoạt động trong Thế chiến thứ hai, trước ENIAC.", "Ba mốc cuối là 1948, 1949, 1951."], "why": "1904 đèn hai cực · 1906 đèn ba cực · 1941 Z3 · 1946 ENIAC được công bố · 1948 Manchester Baby · 1949 EDSAC · 1951 UNIVAC I."}]);

makeQuiz("quiz3","score3",[{"q": "Trong đèn ba cực, điều gì quyết định có dòng điện tới anốt hay không?", "o": ["Màu của bóng thủy tinh", "Điện áp đặt vào lưới", "Độ dài dây nối anốt", "Số đèn trong máy"], "a": 1, "e": "Lưới nằm giữa catốt và anốt; lưới đủ âm thì đẩy electron lại, bớt âm thì cho electron đi qua. Điện áp nhỏ ở lưới điều khiển dòng lớn ở anốt."}, {"q": "Vì sao đèn điện tử đóng ngắt nhanh hơn rơ-le rất nhiều?", "o": ["Vì đèn dùng điện áp cao hơn", "Vì đèn có nhiều tiếp điểm hơn", "Vì đèn không có bộ phận cơ khí phải di chuyển", "Vì đèn nhỏ hơn rơ-le"], "a": 2, "e": "Rơ-le phải kéo tiếp điểm kim loại di chuyển (cỡ mili giây); đèn chỉ đổi điện áp lưới (cỡ micro giây). Đèn thật ra thường to hơn rơ-le."}, {"q": "Máy nào chạy chương trình lưu trong bộ nhớ điện tử đầu tiên, năm 1948?", "o": ["ENIAC", "Z3", "Colossus", "Manchester Baby"], "a": 3, "e": "ENIAC lúc hoàn thành được lập trình bằng dây cắm và công tắc. Manchester Baby chạy chương trình đầu tiên lưu trong bộ nhớ ngày 21/6/1948."}, {"q": "Một máy có 10 000 linh kiện, mỗi linh kiện có MTBF 1 000 000 giờ (hỏng độc lập, một cái hỏng là máy dừng). MTBF của máy khoảng bao nhiêu?", "o": ["100 giờ", "1 000 000 giờ", "10 000 giờ", "10 000 000 000 giờ"], "a": 0, "e": "MTBF máy ≈ 1 000 000 ÷ 10 000 = 100 giờ. Nhân thay vì chia là nhầm lẫn hay gặp: càng nhiều linh kiện thì càng hay hỏng."}, {"q": "Ưu điểm chính của máy tính lưu chương trình so với ENIAC lúc mới hoàn thành là gì?", "o": ["Không cần điện", "Đổi chương trình bằng cách ghi lại bộ nhớ, nhanh như ghi dữ liệu", "Không bao giờ hỏng", "Tính bằng số thập phân"], "a": 1, "e": "Chương trình nằm trong bộ nhớ nên thay chương trình chỉ là ghi dữ liệu mới, không phải nối lại dây. Máy lưu chương trình vẫn có thể hỏng và vẫn cần điện."}]);

